import{_ as o,y as r,a as s,o as i,a2 as e,D as a}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Configuration overview","description":"","frontmatter":{},"headers":[],"relativePath":"configure/introduction.md","filePath":"configure/introduction.md","lastUpdated":1789441803000}'),g={name:"configure/introduction.md"};function h(l,t,d,c,u,f){const n=r("ImagePopup");return i(),s("div",null,[t[0]||(t[0]=e('<h1 id="configuration-overview" tabindex="-1">Configuration overview <a class="header-anchor" href="#configuration-overview" aria-label="Permalink to &quot;Configuration overview&quot;">​</a></h1><p><strong>Configure</strong> holds the settings that decide how your store behaves: units and storefront content, generative AI, shipping and payment, checkout, orders and taxes, the catalog, customer accounts, email, search, file storage and caching. You set most of them once while setting up the store, and come back when something changes.</p><h2 id="open-a-configuration-screen" tabindex="-1">Open a configuration screen <a class="header-anchor" href="#open-a-configuration-screen" aria-label="Permalink to &quot;Open a configuration screen&quot;">​</a></h2><ol><li>In the admin panel, click <strong>Configure</strong> in the left menu.</li><li>Find the group you need, such as <strong>Sales</strong>.</li><li>Click one of its tiles, such as <strong>Checkout</strong>.</li><li>Change the settings.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),a(n,{src:"/images/configure/configuration-index.png",alt:"Configuration page with the General, Magic AI and Sales groups of tiles"}),t[1]||(t[1]=e('<p>Click <strong>Back</strong> to return to the tiles without saving. Two screens have no <strong>Save Configuration</strong> button: <strong>Cache Management &gt;&gt; General</strong>, whose buttons act straight away, and <strong>About</strong>, which only shows information.</p><h2 id="find-a-setting" tabindex="-1">Find a setting <a class="header-anchor" href="#find-a-setting" aria-label="Permalink to &quot;Find a setting&quot;">​</a></h2><ol><li>Go to <strong>Configure</strong>.</li><li>Click the <strong>Search</strong> box at the top of the <strong>Configuration</strong> page.</li><li>Type at least two letters of a screen, section or setting name, such as <code>cookie</code>. The matches appear below the box, each with its full path.</li><li>Click a match to open the screen that holds it.</li></ol>',3)),a(n,{src:"/images/configure/configuration-search.png",alt:"Search box on the Configuration page listing the GDPR settings that match cookie"}),t[2]||(t[2]=e('<p>If nothing matches, the list shows <strong>No result found</strong>.</p><h2 id="settings-per-channel-and-per-language" tabindex="-1">Settings per channel and per language <a class="header-anchor" href="#settings-per-channel-and-per-language" aria-label="Permalink to &quot;Settings per channel and per language&quot;">​</a></h2><p>Some settings can differ from one channel or language to another. The badges beside a field&#39;s label tell you which:</p><ul><li>A field with the channel badge, such as <strong>Default</strong>, is saved for the channel you are editing.</li><li>A field with the language badge, such as <strong>English</strong>, is saved for the language you are editing.</li><li>A field with both badges is saved for that channel and language together.</li><li>A field without a badge applies to the whole store.</li></ul>',4)),a(n,{src:"/images/configure/configuration-scope.png",alt:"GDPR screen with the language selector and the Enable GDPR field marked with the Default and English badges"}),t[3]||(t[3]=e('<p>To change the settings of another channel or language:</p><ol><li>Go to the configuration screen, such as <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</li><li>Choose the channel in the channel selector above the settings.</li><li>Choose the language in the language selector beside it.</li><li>Change the settings.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The channel selector appears only when your store has more than one channel, and the language selector only when the chosen channel offers more than one language. Choosing another channel also switches to that channel&#39;s default language.</p><h2 id="what-each-group-covers" tabindex="-1">What each group covers <a class="header-anchor" href="#what-each-group-covers" aria-label="Permalink to &quot;What each group covers&quot;">​</a></h2><p>The groups appear on the <strong>Configuration</strong> page in this order.</p><table tabindex="0"><thead><tr><th>Group</th><th>Pages</th><th>What you set there</th></tr></thead><tbody><tr><td><strong>General</strong></td><td><a href="./general.html">General</a>, <a href="./content.html">Content</a>, <a href="./design.html">Design</a>, <a href="./exchange-rates-configurations.html">Exchange Rates</a>, <a href="./sitemap.html">Sitemap</a>, <a href="./gdpr.html">GDPR</a></td><td>The weight unit and breadcrumbs, the header offer, footer text, speculation rules and custom scripts, the admin logo and category menu, automatic exchange rates, sitemap limits and privacy consent.</td></tr><tr><td><strong>Magic AI</strong></td><td><a href="./magic-ai.html">Generative AI (Magic AI)</a></td><td>Switching generative AI on, provider API keys, and the AI features of the admin panel and the storefront.</td></tr><tr><td><strong>Sales</strong></td><td><a href="./shipping.html">Shipping Settings</a>, <a href="./../shipping-method/shipping-methods.html">Shipping Methods</a>, <a href="./../payment-method/payment-methods.html">Payment Methods</a>, <a href="./checkout.html">Checkout</a>, <a href="./orders-settings.html">Order Settings</a>, <a href="./invoice-settings.html">Invoice Settings</a>, <a href="./taxes.html">Taxes</a>, <a href="./rma.html">RMA</a>, <a href="./eu-withdrawals.html">EU Withdrawals</a></td><td>Where you ship from, the shipping and payment methods, the cart and checkout, order and invoice numbers, tax calculation, returns and EU withdrawals.</td></tr><tr><td><strong>Catalog</strong></td><td><a href="./configurable-choices.html">Products</a>, <a href="./back-orders.html">Inventory</a>, <a href="./rich-snippets.html">Rich Snippets</a></td><td>Product listings and pages, reviews, sharing, image sizes, upload limits, price disclosure, back orders and structured data for search engines.</td></tr><tr><td><strong>Customer</strong></td><td><a href="./settings.html">Customer Settings</a>, <a href="./address.html">Address</a>, <a href="./google-captcha.html">Google Captcha</a></td><td>New accounts, email verification, sign-in, social login, the wishlist and newsletter, address forms and bot protection.</td></tr><tr><td><strong>Email</strong></td><td><a href="./email-settings.html">Email Settings</a>, <a href="./notifications.html">Notifications</a></td><td>How email is sent, the sender addresses and which emails go out.</td></tr><tr><td><strong>Search Engines</strong></td><td><a href="./search-engines.html">Search Engines</a></td><td>Whether product search runs on the database or on Elasticsearch, and the Elasticsearch connection.</td></tr><tr><td><strong>File Management</strong></td><td><a href="./file-management.html">File Management</a></td><td>Where uploaded files are stored: on the server, in Amazon S3 or in Cloudflare R2.</td></tr><tr><td><strong>Cache Management</strong></td><td><a href="./cache-management.html">Cache Management</a></td><td>Clearing and rebuilding caches, and the storefront&#39;s full page cache.</td></tr><tr><td><strong>About</strong></td><td><a href="./about.html">About</a></td><td>The versions and services your store runs on.</td></tr></tbody></table><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>This guide describes the Configuration screens of Bagisto 2.5. Most of them are the same in Bagisto 2.4, except for these:</p><ul><li><strong>Search Engines</strong>, <strong>File Management</strong> and <strong>About</strong> are new in Bagisto 2.5, and so is the <strong>Omnibus Price Disclosure</strong> section under <strong>Catalog &gt;&gt; Products</strong>.</li><li>In Bagisto 2.4, the search engine and the query length limits are set in the <strong>Search</strong> section under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>. See <a href="./search-engines.html">Search Engines</a>.</li><li>In Bagisto 2.4, <strong>Allow customers to directly buy products</strong> is in the <strong>Storefront</strong> section under <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>. In Bagisto 2.5 it is in <strong>Product view page configuration</strong>.</li><li>In Bagisto 2.4, the cart icon&#39;s <strong>Summary</strong> has its own <strong>My Cart</strong> section under <strong>Configure &gt;&gt; Sales &gt;&gt; Checkout</strong>. In Bagisto 2.5 it is in <strong>Mini Cart</strong>.</li><li>The <strong>Full Page Cache</strong> screen under <strong>Cache Management</strong>, the <strong>PayGlocal</strong> payment method and the <strong>Driver</strong> setting under <strong>Email Settings &gt;&gt; Mail Driver</strong> arrived in Bagisto 2.4.10, so releases before 2.4.10 don&#39;t have them. See <a href="./cache-management.html">Cache Management</a> and <a href="./email-settings.html">Email Settings</a>.</li></ul>',9))])}const C=o(g,[["render",h]]);export{p as __pageData,C as default};
